EVENT_GEOLOCATION_LOCALES = frozenset(EVENT_GEOLOCATION_ROWS)
EVENT_GEOLOCATION_TRANSLATIONS: dict[str, dict[str, str]] = {
    locale: dict(zip(EVENT_GEOLOCATION_KEYS, row.split("|"), strict=True))
    for locale, row in EVENT_GEOLOCATION_ROWS.items()
}

if EVENT_GEOLOCATION_LOCALES != EXPECTED_EVENT_GEOLOCATION_LOCALES:
    raise ValueError("Events geolocation catalog locale coverage is incomplete")
if len(set(EVENT_GEOLOCATION_KEYS)) != len(EVENT_GEOLOCATION_KEYS):
    raise ValueError("Events geolocation catalog source keys must be unique")
if any(
    set(entries) != set(EVENT_GEOLOCATION_KEYS)
    for entries in EVENT_GEOLOCATION_TRANSLATIONS.values()
):
    raise ValueError("Events geolocation catalog source coverage is incomplete")

_formatter = Formatter()
for _locale, _entries in EVENT_GEOLOCATION_TRANSLATIONS.items():
    for _source, _translation in _entries.items():
        if not _translation.strip() or _translation == _source:
            raise ValueError(
                f"Events geolocation translation is missing for {_locale}: {_source}"
            )
        _source_slots = Counter(
            field
            for _literal, field, _spec, _conversion in _formatter.parse(_source)
            if field
        )
        _translated_slots = Counter(
            field
            for _literal, field, _spec, _conversion in _formatter.parse(
                _translation
            )
            if field
        )
        if _source_slots != _translated_slots:
            raise ValueError(
                f"Events geolocation placeholder mismatch for {_locale}: {_source}"
            )
